SELECT

FROM reservation
WHERE user_id = #{userId}

    AND status = #{status}

ORDER BY reservation_date DESC, start_time DESC

SELECT

FROM reservation
WHERE user_id = #{userId}

    AND status = #{status}

ORDER BY CASE WHEN status = 0 THEN 0 ELSE 1 END, approve_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM reservation
WHERE user_id = #{userId}

    AND status = #{status}

SELECT

FROM reservation

    WHERE status = #{status}

ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM reservation

    WHERE status = #{status}

SELECT

FROM reservation
WHERE meeting_room_id = #{roomId}
AND reservation_date = #{date}
AND status IN (0, 1)
AND (
    (start_time < #{endTime} AND end_time > #{startTime})
)

    AND id != #{excludeId}

