UPDATE reservation
meeting_title = #{meetingTitle}, reservation_date = #{reservationDate}, start_time = #{startTime}, end_time = #{endTime}, attendee_count = #{attendeeCount}, status = #{status}, reject_reason = #{rejectReason}, approve_time = #{approveTime}, approver_id = #{approverId},
WHERE id = #{id}
